UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"History","headingLine1":"Founded in Conviction.","headingAccent":"Grown in Purpose.","paragraphs":["Bodhisattva International was founded in the 1980s by Anjana Shakya and her late husband Purna Man Shakya, guided by a philosophy they called ''The Art of Living''. What began as a commitment to commissioning and collecting the finest Newa art grew into a family mission: to build a renaissance of contemporary traditional Newa art, made to museum quality rather than for mass production.","Through Bodhisattva Gallery, the family has presented more than 24 major exhibitions in Nepal and abroad — from Jewels of Newar Art in Kathmandu to Nepal Art Now at the Weltmuseum Wien — and contributed works to international museum collections. In 2023 the Purna Museum of Newa Art opened in Kupondole, Lalitpur, housing the couple''s permanent collection: the world''s largest private collection dedicated to contemporary traditional Newa art.","Today Bodhisattva International unites four arms — the Purna Museum of Newa Art, Bodhisattva Gallery, the Bodhisattva Foundation, and the Bodhisattva Gift Shop — preserving sacred knowledge, nurturing artists, and building bridges across generations and geographies."],"image":{"url":"/images/pages/about-history.jpg","alt":"Painted Lakhey mask from the Nepal Art Now exhibition at Weltmuseum Wien"},"imageAspect":"16:9","quote":{"text":"Art is not only to be preserved, but lived; not only to be admired, but experienced; and not only to represent culture, but to sustain it.","attribution":"Bodhisattva International"}}' WHERE p.`slug` = 'about' AND ps.`sort_order` = 1;
--> statement-breakpoint
UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"layout":"two-column statements","columns":[{"label":"Our Vision","emphasis":"display","body":"A living civilization, not a static heritage — Newa art that remains active, relevant and deeply rooted in its spiritual origins while engaging with contemporary global culture."},{"label":"Our Mission","emphasis":"body","body":"To preserve, elevate and reimagine the sacred artistic traditions of the Kathmandu Valley — sustaining art, supporting artists, educating communities, and sharing Nepal''s spiritual visual heritage on a global stage."}]}' WHERE p.`slug` = 'about' AND ps.`sort_order` = 2;
