UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"Our Purpose","headingLine1":"A Living Archive of","headingAccent":"Sacred Civilization","paragraphs":["Bodhisattva International is a cultural institution in Kupondole, Lalitpur, dedicated to preserving, elevating, and reimagining the sacred artistic traditions of Nepal. Founded in the 1980s by Anjana Shakya and the late Purna Man Shakya, it unites the Purna Museum of Newa Art, Bodhisattva Gallery, the Bodhisattva Foundation, and the Bodhisattva Gift Shop.","We believe that art is not only to be preserved, but lived; not only to be admired, but experienced; and not only to represent culture, but to sustain it."],"cta":{"kind":"page","label":"Our Story","pageId":7},"image":{"url":"/images/pages/home-intro.jpg","alt":"Paubha painting of a goddess by Udaya Charan Shrestha"},"imageAspect":"4:5","calloutBadge":{"value":"24+","label":"Major Exhibitions"}}' WHERE p.`slug` = 'home' AND ps.`sort_order` = 1;
