UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"Overview","headingLine1":"A Living Archive","headingAccent":"of Devotion.","paragraphs":["Opened in 2023 with the inaugural exhibition A Collector''s Collection, the Purna Museum of Newa Art is a landmark institution and the world''s largest private collection dedicated to contemporary traditional Newa art. It was officially inaugurated by Minister of Education, Science and Technology Ashok Rai, UNESCO Representative to Nepal Michael Croft, and Co-Founder of Bodhisattva International Anjana Shakya.","The museum houses the permanent collection of Anjana Shakya and the late Purna Man Shakya, fulfilling his vision of a space where people could experience the finest Newa art in Nepal, without having to travel abroad to see their own heritage. Its collection spans paubha, lost-wax bronze sculpture, repoussé, and miniature art on precious and semi-precious stones."],"facts":[{"label":"Established","value":"2023"},{"label":"Collection","value":"Anjana & Purna Man Shakya"},{"label":"Art Forms","value":"Paubha · Bronze · Repoussé · Miniature"},{"label":"Location","value":"Kupondole, Lalitpur"},{"label":"Opening Hours","value":"12 PM – 6 PM"},{"label":"Closed","value":"Mondays"}]}' WHERE p.`slug` = 'museum' AND ps.`sort_order` = 1;
