INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('ten-years-of-celebrating-embodied-enlightenment', '10 Years of Celebrating Embodied Enlightenment', 'A retrospective exhibition of Samundra Man Singh Shrestha by Bodhisattva International. For the first time in the history of Nepali art, an exhibition is re-celebrated a decade later: Embodied Enlightenment returns, bringing audiences back to the original 2016 retrospective while revealing how its artist has evolved over the past ten years. Works from the private collection of Anjana and the late Purna Man Shakya, originally presented in the landmark exhibition, are shown alongside new and previously unseen works by the artist. Inaugurated by former Crown Princess Himani Shah; open daily 12 PM – 7 PM, entry Rs. 200 in support of the Prime Minister''s Disaster Relief Fund.', 'Purna Museum of Newa Art & Bodhisattva Gallery, Kupondole', '2026-11-16', '2026-12-27', 'CURRENT', 'Prajwol Man Shakya', 'buddhist', 'tall', '/images/exhibitions/ten-years-of-celebrating-embodied-enlightenment.jpg', '10 Years of Celebrating Embodied Enlightenment — retrospective poster with the blue wrathful deity painting', 1, 1, 0) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('a-collectors-collection', 'A Collector''s Collection', 'The exhibition that officially opened the Purna Museum of Newa Art, inaugurated by Minister of Education, Science and Technology Ashok Rai, UNESCO Representative to Nepal Michael Croft, and Co-Founder Anjana Shakya. Featuring the permanent collection of Anjana and the late Purna Man Shakya, it traced the evolution from traditional souvenir-oriented works to technically refined, museum-quality masterpieces — a glimpse into Purna Man Shakya''s lasting role in shaping the renaissance of contemporary Newa art.', 'Purna Museum of Newa Art, Kupondole, Lalitpur', '2023-09-02', '2024-02-02', 'PAST', 'Prajwol Man Shakya', 'contemporary', 'standard', '/images/exhibitions/a-collectors-collection.jpg', 'A Collector''s Collection poster — a visitor studying a paubha with a magnifying lens', 0, 1, 1) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('small-wonders-great-devotion', 'Small Wonders Great Devotion: Sacred Treasures of the Kathmandu Valley', 'A miniature art exhibition bringing together 117 miniature artworks, each under 9 inches and some as small as 0.25 cm — paubha paintings, bronze and copper statues, gold and silver repoussé, and finely carved turquoise, coral and black stone sculptures, sourced primarily from the private archives of Anjana and the late Purna Man Shakya. These microscopic masterpieces show how immense spiritual depth and technical mastery can exist within the smallest forms.', 'Purna Museum of Newa Art, Kupondole, Lalitpur', '2025-02-28', '2025-11-30', 'PAST', 'Prajwol Man Shakya', 'thematic', 'tall', '/images/exhibitions/small-wonders-great-devotion.jpg', 'Small Wonders Great Devotion poster — collage of miniature paintings and statues', 0, 1, 2) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('whispers-of-the-divine', 'Whispers of the Divine', 'A landmark three-phase exhibition presenting the work of master painter Udaya Charan Shrestha, a leading figure in contemporary Newar paubha art, inaugurated by Véronique Lorenzo, Ambassador of the European Union to Nepal. Fourteen years in the making, the collection began in 2010 through a long-term relationship between the artist and the Shakya family; every work was commissioned directly from Shrestha, except one painting acquired through a reseller. Rare and previously unseen hyper-realistic paubha paintings, many exhibited publicly for the first time.', 'Purna Museum of Newa Art, Kupondole, Lalitpur', '2025-05-04', '2025-11-30', 'PAST', 'Prajwol Man Shakya', 'buddhist', 'tall', '/images/exhibitions/whispers-of-the-divine.jpg', 'Whispers of the Divine poster — pencil drawing of a goddess holding a sword', 0, 1, 3) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('ucchushma-jambhalas-dhuku', 'Ucchushma Jambhala''s Dhuku', 'Ucchushma Jambhala''s Dhuku — the Room of Ucchushma Jambhala, or Black Jambhala — was the final exhibition envisioned by the late Purna Man Shakya. Inspired by Udaya Charan Shrestha''s original painting, he commissioned a ten-year project encompassing a monumental lost-wax bronze statue, miniature stone works, silver repoussé, and a larger full-colour rendition of the original painting. The bronze statue''s wax model alone took four years (3,360 hours), followed by eight months of intensive carving by Aneel and Suman Shakya. Inaugurated by Deputy Mayor of Kathmandu Metropolitan City Sunita Dangol, the exhibition was completed and presented after Purna Man Shakya''s passing.', 'Purna Museum of Newa Art, Kupondole, Lalitpur', '2024-05-19', '2025-01-19', 'PAST', 'Prajwol Man Shakya', 'buddhist', 'tall', '/images/exhibitions/ucchushma-jambhalas-dhuku.jpg', 'Ucchushma Jambhala''s Dhuku poster — golden Jambhala statue beside the blue-black deity painting', 0, 1, 4) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('the-art-of-babu-kaji-bajracharya', 'The Art of Babu Kaji Bajracharya', 'A first-of-its-kind solo exhibition dedicated to a traditional Newa statue maker, celebrating one of Nepal''s senior living master wax-model makers at the age of 83. Spanning the 1990s to 2026, it brought together early works and final cast statues in bronze, copper and silver, all from the collections of Anjana Shakya, the late Purna Man Shakya and Bodhisattva Gallery. Inaugurated by Deputy Mayor of Lalitpur Manjali Shakya Bajracharya, with a special edition catalogue documenting his contribution to traditional Newa statue making.', 'Bodhisattva Gallery, Kupondole, Lalitpur', '2026-07-11', '2026-07-31', 'PAST', 'Prajwol Man Shakya', 'contemporary', 'tall', '/images/exhibitions/the-art-of-babu-kaji-bajracharya.jpg', 'The Art of Babu Kaji Bajracharya poster — bronze statues of seated female figures', 0, 1, 5) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
