INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('trinity-of-compassion', 'Trinity of Compassion: Buddha | Tara | Avalokiteshvara', 'The exhibition explored the profound relationship between three central figures of Mahayana and Vajrayana Buddhism: the Buddha as enlightened wisdom, Tara as active compassion, and Avalokiteshvara as boundless mercy. Rather than separate deities, they are presented as interconnected expressions of a single enlightened continuum — a unified vision of enlightenment that is active, relational and ever-present.', 'Bodhisattva Gallery, Kupondole, Lalitpur', '2025-08-02', '2026-04-30', 'PAST', 'Prajwol Man Shakya', 'buddhist', 'tall', '/images/exhibitions/trinity-of-compassion.jpg', 'Trinity of Compassion poster — gilded Buddha statue in an ornate torana', 0, 1, 6) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
