INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('sacred-forms', 'Sacred Forms: Honouring Udaya Charan Shrestha''s Artistic Legacy & Inspired Works', 'A landmark exhibition celebrating the artistic legacy of Udaya Charan Shrestha, one of the most influential modern masters of paubha art. Rather than presenting his work in isolation, it explored the artistic dialogue surrounding his practice — works by his brothers Mahesh Shrestha and Dinesh Charan Shrestha, his daughter Neeti Shrestha, collaborative works, and a special section of works inspired by his art. The result of more than 14 years of dedicated collecting. A parallel presentation, Whispers of the Divine, ran at the Purna Museum of Newa Art.', 'Bodhisattva Gallery, Kupondole, Lalitpur', '2025-05-04', '2025-07-05', 'PAST', 'Prajwol Man Shakya', 'buddhist', 'tall', '/images/exhibitions/sacred-forms.jpg', 'Sacred Forms poster — vertical strips of colourful deity paintings', 0, 1, 7) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
