INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('pancha-pranali', 'Pancha Pranali', 'Pancha Pranali was a pioneering cultural project by Miss Nepal World 2023 Srichchha Pradhan, created for the Miss World ''Beauty with a Purpose'' initiative. It brought ancient Newa cosmology to a global stage, using the five elemental principles — earth, water, fire, air and space — as a framework for contemporary ecological awareness, with interactive workshops, guided sessions and talks alongside the exhibition.', 'Bodhisattva Gallery, Kupondole, Lalitpur', '2024-12-21', '2024-12-27', 'PAST', 'Srichchha Pradhan, Prajwol Man Shakya', 'thematic', 'standard', '/images/exhibitions/pancha-pranali.jpg', 'Pancha Pranali poster — five element symbols among pink lotus flowers', 0, 1, 8) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
