INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('shakti-divine-feminine-power', 'Shakti: Divine Feminine Power of Hindu and Buddhist Deities', 'Exploring the divine feminine as the creative and transformative force of existence, rooted in Hindu and Buddhist philosophical traditions. Through powerful depictions of Kali, Durga, Vajrayogini and other manifestations, the exhibition revealed Shakti as a living cosmic force encompassing compassion, nurturing, destruction and renewal. A highlight was Search for Shakti, a fusion of Charya Nritya and Bharatanatyam honouring Arya Tara, Kaumari, Annapurna and Gujeshwori. Shown in two series: 14 September – 5 October and 8 – 30 October 2024.', 'Bodhisattva Gallery, Kupondole, Lalitpur', '2024-09-14', '2024-10-30', 'PAST', 'Prajwol Man Shakya', 'thematic', 'tall', '/images/exhibitions/shakti-divine-feminine-power.jpg', 'Shakti poster — golden repoussé plaque of a multi-armed goddess', 0, 1, 9) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
