INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('buddhist-connections-in-the-snowyland', 'Buddhist Connections in the Snowyland: Nepalese Fine Art Exhibition', 'The first dedicated presentation of Newa art in China, hosted at Lan Gallery, Beijing, and organised by the Embassy of Nepal in China and the Silk Road Cities Alliance. Featuring 32 masterworks of sculpture and painting, it highlighted the shared Buddhist heritage connecting Nepal, Tibet and China through centuries of artistic and spiritual dialogue — a living act of cultural diplomacy.', 'Lan Gallery, Beijing, China', '2024-08-29', '2024-09-05', 'PAST', 'Siddhartha Man Shakya', 'buddhist', 'tall', '/images/exhibitions/buddhist-connections-in-the-snowyland.jpg', 'Buddhist Connections in the Snowyland poster — framed paubha of a dancing deity', 0, 1, 10) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
