INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('wealth-deities-guardians-of-prosperity', 'Wealth Deities: Guardians of Prosperity', 'The exhibition explored the meaning of abundance within Newa spiritual traditions through deities such as Jambhala, Vasudhara, Lakshmi and Ganesh. Featuring selected paubha and statues, it highlighted wealth not as material gain alone, but as a path toward generosity, balance and spiritual growth — explaining symbolic elements such as Jambhala''s jewel-spitting mongoose and Vasudhara''s overflowing grain.', 'Bodhisattva Gallery, Kupondole, Lalitpur', '2024-05-19', '2024-08-31', 'PAST', 'Prajwol Man Shakya', 'buddhist', 'tall', '/images/exhibitions/wealth-deities-guardians-of-prosperity.jpg', 'Wealth Deities poster — golden Jambhala statue against black', 0, 1, 11) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
