INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('prakriti-where-the-gods-reside', 'Prakriti: Where the Gods Reside', 'Prakriti invited audiences to understand the universe itself as sacred, and the five elements of nature — earth, water, fire, air and space — as essential forces that sustain life. It featured a life-sized projection-mapped animation of Goddess Annapurna, abstract paubha by master artist Raj Prakash Tuladhar, bird-feather paintings by Puspa Lal Dangol, and intricate filigree bird sculptures by Pradip Shakya — Newa art as a living tradition speaking to nature, sustainability and climate change.', 'Bodhisattva Gallery, Kupondole, Lalitpur', '2023-08-07', '2023-08-21', 'PAST', 'Prajwol Man Shakya', 'thematic', 'standard', '/images/exhibitions/prakriti-where-the-gods-reside.jpg', 'Prakriti poster — embracing divine couple amid clouds and flames', 0, 1, 12) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
