INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('karunamayas-karuna', 'Karunamaya''s Karuna', 'An immersive exhibition exploring Avalokiteshvara — the Bodhisattva of Compassion, known locally as Karunamaya. Featuring 31 paintings and 11 sculptures presenting 26 manifestations of the deity, it guided visitors through a narrative progression enhanced by Nepal''s first private gallery audio tour and digital projections, including Karunamaya saving souls from the Avichi Hell and a Charya Nritya performance by Raju Shakya. Two Avalokiteshvara statues in the show had been exhibited in Vienna for almost a year in 2019.', 'Bodhisattva Gallery, Kupondole, Lalitpur', '2022-02-24', '2022-04-16', 'PAST', 'Prajwol Man Shakya', 'buddhist', 'tall', '/images/exhibitions/karunamayas-karuna.jpg', 'Karunamaya''s Karuna poster — golden Avalokiteshvara statue against black', 0, 1, 13) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
