INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('compassion-and-healing-through-taras', 'Compassion & Healing Through Taras', 'Emerging in the aftermath of the COVID-19 pandemic, Compassion & Healing Through Taras was conceived as both an exhibition and a spiritual offering dedicated to communal healing. It featured paubha, sculptures, carved semi-precious stones, and gold and silver repoussé exploring the many forms of Tara — the embodiment of compassion and swift action. The opening programme included a talk on Tara iconography by Rev. Deepak Bajracharya and a sacred Charya Nritya performance by Raju Shakya and his team; the exhibition also introduced digital projection in the gallery for the first time.', 'Bodhisattva Gallery, Kupondole, Lalitpur', '2021-10-10', '2021-12-12', 'PAST', 'Prajwol Man Shakya', 'buddhist', 'tall', '/images/exhibitions/compassion-and-healing-through-taras.jpg', 'Compassion & Healing Through Taras poster — Green Tara painting', 0, 1, 14) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
