INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('nepal-art-now', 'Nepal Art Now: Contemporary Nepalese Art', 'Held at the Weltmuseum Wien, Nepal Art Now was the largest and most comprehensive exhibition of contemporary Nepalese art outside Nepal, with around 130 works by approximately 40 artists. Major loaned works from Bodhisattva Gallery and the private collection of Anjana and the late Purna Man Shakya — including a wooden and bronze Standing Padmapani Lokeshvara and the Vajrapani painting — served as cultural anchors of the exhibition, affirming Purna Man Shakya''s legacy as a collector and cultural custodian.', 'Weltmuseum Wien, Vienna, Austria', '2019-04-11', '2019-11-08', 'PAST', NULL, 'contemporary', 'standard', '/images/exhibitions/nepal-art-now.jpg', 'Nepal Art Now poster — red-and-white Lakhey mask painting', 0, 1, 15) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
