INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('jewels-of-newar-art-second-edition', 'Jewels of Newar Art — Second Edition', 'The second edition of Jewels of Newar Art marked the opening of Bodhisattva Gallery''s permanent space in Pulchowk, Lalitpur, inaugurated by Hon. Sashi Shrestha, former Minister of Land Management, Cooperatives and Poverty Alleviation. Designed by Siddhartha Man Shakya and curated by Prajwol Man Shakya, the gallery created an immersive, contemplative atmosphere through controlled lighting and dramatic spotlighting. Featuring over 75 master artists in painting, stone carving and statues, it celebrated the living evolution of contemporary Newa craftsmanship.', 'Bodhisattva Gallery, Pulchowk, Lalitpur', '2019-01-20', '2019-02-09', 'PAST', 'Prajwol Man Shakya', 'historical', 'standard', '/images/exhibitions/jewels-of-newar-art-second-edition.jpg', 'Jewels of Newar Art second edition invitation — yellow standing deity painting', 0, 1, 16) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
