INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('embodied-enlightenment-2016', 'Embodied Enlightenment', 'A landmark retrospective dedicated to artist Samundra Man Singh Shrestha, organised by Bodhisattva Gallery at the Nepal Art Council. Featuring over 62 works, it highlighted the artist''s distinctive fusion of classical Newa iconography with realism, depth and contemporary artistic expression, and drew more than 6,000 visitors in just 11 days. Of the works presented, 45 belonged to the Shakya family, assembled over five years by purchasing important works from collectors in Nepal and abroad and commissioning new works directly from the artist; the remaining works were loaned by the artist and private collectors from Nepal, China and London. The exhibition produced a scholarly catalogue and introduced high-quality giclée prints on cotton canvas.', 'Nepal Art Council, Babar Mahal, Kathmandu', '2016-05-29', '2016-06-09', 'PAST', 'Dina Bangdel & Prajwol Man Shakya', 'buddhist', 'tall', '/images/exhibitions/embodied-enlightenment-2016.jpg', 'Embodied Enlightenment 2016 poster — blue wrathful deity painting', 0, 1, 17) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
