INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('jewels-of-newar-art-hyatt-regency', 'Jewels of Newar Art — Hyatt Regency Kathmandu Edition', 'Following the success of the 2011 exhibition, Bodhisattva Gallery organised a series of annual and biannual exhibitions at Hyatt Regency Kathmandu between 2012 and 2018. Set within a luxury international venue, these exhibitions introduced museum-quality Newa paubha and sculptures to global travellers, collectors, diplomats and spiritual leaders, helping reposition Newa art as collectible fine art rather than ethnographic artefact, and building an international collector base for contemporary traditional Newa art.', 'Hyatt Regency Kathmandu, Taragaon, Kathmandu', '2012-01-01', '2018-12-31', 'PAST', 'Bodhisattva Gallery Team', 'historical', 'standard', '/images/exhibitions/jewels-of-newar-art-hyatt-regency.jpg', 'Jewels of Newar Art at Hyatt Regency — Chaitya Court exhibition graphic', 0, 1, 18) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
