INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('royal-fables', 'Royal Fables', 'In October 2011, Bodhisattva Gallery made its first appearance outside Nepal, participating in Royal Fables Season 2 at The Metropolitan Hotel in New Delhi — a concept exhibition by Anshu Khanna, organised by Khushii and RoyalFables, bringing together the cultural heritage, craftsmanship and contemporary creativity inspired by the royal families of India. Presenting traditional Newa art alongside creations inspired by India''s royal traditions, the gallery introduced Nepal''s Newa artistic heritage to an international audience.', 'The Metropolitan Hotel, Connaught Place, New Delhi, India', '2011-10-14', '2011-10-16', 'PAST', NULL, 'thematic', 'tall', '/images/exhibitions/royal-fables.jpg', 'Royal Fables poster — portrait of a king in an ornate gold frame', 0, 1, 19) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `exhibitions` (`slug`, `title`, `description`, `location`, `starts_on`, `ends_on`, `status`, `curator`, `category`, `cover_aspect`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('jewels-of-newar-art-2011', 'Jewels of Newar Art 2011', 'The first Jewels of Newar Art exhibition, presented by Bodhisattva Gallery in collaboration with Siddhartha Art Gallery: 65 paubha paintings and 10 sculptures by more than two dozen Newar artists, collected by Purna Man Shakya over 25 years. Inaugurated by Dr. Dina Bangdel, the exhibition also launched the Jewels of Newar Art book, and its Sunday talk programme covered the Arniko legacy, oil in paubha painting, lost-wax statue making, and paubha and spirituality.', 'Siddhartha Art Gallery, Babar Mahal Revisited, Kathmandu', '2011-04-26', '2011-05-15', 'PAST', 'Sangeeta Thapa and Bodhisattva Gallery Team', 'historical', 'tall', '/images/exhibitions/jewels-of-newar-art-2011.jpg', 'Painting of a standing goddess in an ornate torana — Jewels of Newar Art 2011', 0, 1, 20) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `description` = VALUES(`description`), `location` = VALUES(`location`), `starts_on` = VALUES(`starts_on`), `ends_on` = VALUES(`ends_on`), `status` = VALUES(`status`), `curator` = VALUES(`curator`), `category` = VALUES(`category`), `cover_aspect` = VALUES(`cover_aspect`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `collections` (`slug`, `name`, `category`, `period_label`, `description`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('paubha-paintings', 'Paubha Paintings', 'Painting', NULL, 'Paubha — derived from the Sanskrit pata, cloth painting — is the Kathmandu Valley''s sacred painting tradition: large vertical-format paintings of deities, mandalas and narratives, executed to the iconometric grids and proportions laid down in treatises such as the Vishnudharmottara Purana. The earliest dated paubha, the Vasudhara Mandala, was painted in 1365 AD. The collection holds contemporary traditional paubha by the valley''s master painters, commissioned and collected by Anjana and Purna Man Shakya over four decades.', '/images/collections/paubha-paintings.jpg', 'Paubha painting of a blue wrathful deity', 1, 1, 0) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `category` = VALUES(`category`), `period_label` = VALUES(`period_label`), `description` = VALUES(`description`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `collections` (`slug`, `name`, `category`, `period_label`, `description`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('lost-wax-bronze-sculpture', 'Lost-Wax Bronze Sculpture', 'Sculpture', NULL, 'Statues cast by the lost-wax process — a technique Newar metalworkers have practised for centuries and carried to Tibet, China and Bhutan. The collection spans monumental bronzes, including the Ucchushma Jambhala whose wax model alone took four years (3,360 hours) to complete, and the work of master statue makers such as Babu Kaji Bajracharya, whose wax models are cast by fellow masters in bronze, copper and silver.', '/images/collections/lost-wax-bronze-sculpture.jpg', 'Golden Jambhala bronze statue at Purna Museum of Newa Art', 1, 1, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `category` = VALUES(`category`), `period_label` = VALUES(`period_label`), `description` = VALUES(`description`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `collections` (`slug`, `name`, `category`, `period_label`, `description`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('repousse', 'Repoussé', 'Sculpture', NULL, 'Gold and silver repoussé — metal hammered into relief from behind — is among the most demanding of Newa crafts, and a specialisation of the gallery since the 1980s. The collection''s repoussé works range from ritual plaques to miniature panels on precious metal, including the silver repoussé created for Ucchushma Jambhala''s Dhuku.', '/images/collections/repousse.jpg', 'Golden repoussé plaque of a multi-armed goddess', 1, 1, 2) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `category` = VALUES(`category`), `period_label` = VALUES(`period_label`), `description` = VALUES(`description`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `collections` (`slug`, `name`, `category`, `period_label`, `description`, `image_url`, `image_alt`, `is_featured`, `is_published`, `sort_order`) VALUES ('miniature-art-on-precious-stones', 'Miniature Art on Precious & Semi-Precious Stones', 'Miniatures', NULL, 'Miniature paintings and carvings on precious and semi-precious stones — turquoise, coral and black stone among them — some as small as 0.25 cm. The museum''s Small Wonders Great Devotion exhibition brought together 117 such miniature works: paubha paintings, bronze and copper statues, gold and silver repoussé, and finely carved stone sculptures from the collection.', '/images/collections/miniature-art.jpg', 'Miniature paintings and statues — Small Wonders Great Devotion', 0, 1, 3) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `category` = VALUES(`category`), `period_label` = VALUES(`period_label`), `description` = VALUES(`description`), `image_url` = VALUES(`image_url`), `image_alt` = VALUES(`image_alt`), `is_featured` = VALUES(`is_featured`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `foundation_programs` (`slug`, `name`, `category`, `description`, `impact_label`, `icon_name`, `is_published`, `sort_order`) VALUES ('purna-man-shakya-memorial-art-award', 'Purna Man Shakya Memorial Art Award', 'Art Award', 'First presented in 2023 by the Bodhisattva Foundation, the award honours the founders'' philosophy of artistic excellence for both senior and emerging artists. Held at Bodhisattva Gallery in two categories — paubha painting and traditional sculpture — it encourages artists to move beyond repetition and mass production toward mastery, innovation and depth. Winners — 2023: Raj Prakash Tuladhar, Sujit Maharjan and Ram Prakash Shrestha (paubha); Shyam Maharjan (statue). 2024: Ram Prakash Shrestha, Priya Shakya and Amrit Dangol (paubha); Niraj Shakya, Birendra Shakya and Rajiv Tandukar (statue). 2025: Ritesh Shahi, Devendra Sinkhwal and Sankha Narayan Shrestha (paubha).', 'Rs. 50,000 first prize · 3 editions since 2023', 'Award', 1, 0) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `category` = VALUES(`category`), `description` = VALUES(`description`), `impact_label` = VALUES(`impact_label`), `icon_name` = VALUES(`icon_name`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `foundation_programs` (`slug`, `name`, `category`, `description`, `impact_label`, `icon_name`, `is_published`, `sort_order`) VALUES ('humanitarian-support', 'Humanitarian Support', 'Humanitarian', 'Beyond art, the Foundation carries forward Purna Man Shakya''s quiet legacy of humanity: supporting children''s education, funding medical treatment for those in need, and offering protection and support to individuals during Nepal''s periods of political conflict. Alongside him, Anjana Shakya shared — and continues to carry forward — these values of compassion and service, placing human dignity and kindness at the heart of the work.', 'Education · Medical aid · Community support', 'Users', 1, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `category` = VALUES(`category`), `description` = VALUES(`description`), `impact_label` = VALUES(`impact_label`), `icon_name` = VALUES(`icon_name`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
INSERT INTO `foundation_programs` (`slug`, `name`, `category`, `description`, `impact_label`, `icon_name`, `is_published`, `sort_order`) VALUES ('art-education-talks-and-workshops', 'Art Education, Talks & Workshops', 'Education', 'An ongoing programme of lectures, talk series and workshops keeps Newa art in living conversation — from Dr. Dina Bangdel''s talks on sacred Newar art and paubha painting, and Udaya Charan Shrestha''s lecture series on Ucchushma Jambhala, to hands-on workshops teaching school students paubha painting and the lost-wax process, and conversations on art, climate and heritage at the Gallery and the Museum.', 'Lectures & workshops since 2013', 'BookOpen', 1, 2) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `category` = VALUES(`category`), `description` = VALUES(`description`), `impact_label` = VALUES(`impact_label`), `icon_name` = VALUES(`icon_name`), `is_published` = VALUES(`is_published`), `sort_order` = VALUES(`sort_order`);
--> statement-breakpoint
