INSERT INTO `news_articles` (`slug`, `title`, `category_id`, `article_type`, `outlet`, `author`, `published_on`, `summary`, `content`, `content_plain`, `image_url`, `image_alt`, `is_published`) VALUES ('into-the-exquisite-world-of-religious-art', 'Into the exquisite world of religious art', (SELECT `id` FROM `news_categories` WHERE `slug` = 'feature'), (SELECT `name` FROM `news_categories` WHERE `slug` = 'feature'), 'The Kathmandu Post', 'Shranup Tandukar', '2022-03-10', 'Shranup Tandukar''s full-page feature on Bodhisattva Gallery''s exhibition ''Karunamaya''s Karuna'' at Pulchowk Road, Lalitpur — 31 paintings and statues curated largely from the Shakya family''s own collection, with a guided audio tour — exploring how the show demystifies Buddhist statue making and paubha art.', 'Into the exquisite world of religious art
                           Bodhisattva Gallery’s ongoing exhibition, ‘Karunamaya’s Karuna’, attempts to shed
                               light on and demystify the art of Buddhist statue making and paubha art.
SHRANUP TANDUKAR
LALITPUR




T
            he beauty of art lies in its
            ability to impact us. To
            make us think, feel, see,
            touch, smell, taste, and
            experience things from a
            new vantage point. Art
can also be unexpected; a trip to
an art exhibition can be an amazing,
underwhelming, resonant, nostalgic,
confounding, or sometimes, a
learning experience.
   Religious art can be particularly
cryptic to people unaware of the
religious motifs and history. Paubha,
a genre of traditional painting
that originated among the Newa
inhabitants of the Valley, is a form of
religious art that can be baffling to
many. While the primary deity promi-
nently featured in paubha paintings
can be familiar, the meaning and sig-
nificance of the specific pose of the
deity, motifs used in the painting,
colour scheme, and imageries can
remain enigmatic.
   An attempt to shed light and demys-
tify paubha art as well as Buddhist
statues is seen at the Bodhisattva
Gallery’s      ongoing     exhibition,
